function getParam(name) {
  return new URL(window.location.href).searchParams.get(name);
}

async function loadJSON(path) {
  const r = await fetch(path);
  if (!r.ok) {
    throw new Error(`Failed to load ${path}: ${r.status}`);
  }
  return await r.json();
}

function fmt(x, nd = 2) {
  return (typeof x === 'number' && Number.isFinite(x)) ? x.toFixed(nd) : '';
}

function fmtSmart(x) {
  if (!(typeof x === 'number' && Number.isFinite(x))) return '';
  const ax = Math.abs(x);
  if (ax >= 100) return x.toFixed(0);
  if (ax >= 10) return x.toFixed(1);
  if (ax >= 1) return x.toFixed(2);
  if (ax >= 0.1) return x.toFixed(3);
  if (ax >= 0.01) return x.toFixed(4);
  return x.toExponential(2);
}

function escapeHTML(s) {
  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function ticBucket(tic) {
  const s = String(tic).padStart(9, '0');
  return s.slice(0, 3);
}

function hexPath(cx, cy, r) {
  const pts = [];
  for (let i = 0; i < 6; i++) {
    const a = Math.PI / 3 * i + Math.PI / 6;
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return 'M ' + pts.map(p => `${p[0]},${p[1]}`).join(' L ') + ' Z';
}

function getSectorsArray(data) {
  const sectorsRaw = data && data.sectors ? data.sectors : [];
  return Array.isArray(sectorsRaw) ? sectorsRaw : Object.values(sectorsRaw);
}

function getFeatureTransform(metric, useLogRequested) {
  const forceNoLog = ['ratio', 'Trust', 'Cont', 'topo_errRate'];
  const useLog = useLogRequested && !forceNoLog.includes(metric);

  function forward(v) {
    if (!(typeof v === 'number' && Number.isFinite(v))) return NaN;
    if (!useLog) return v;
    return Math.log10(Math.max(v, 1e-12));
  }

  function label() {
    return useLog ? `log10(${metric})` : metric;
  }

  return { useLog, forward, label };
}

function interpChannel(stops, t) {
  if (t <= 0) return stops[0][1];
  if (t >= 1) return stops[stops.length - 1][1];
  for (let i = 0; i < stops.length - 1; i++) {
    const t0 = stops[i][0];
    const t1 = stops[i + 1][0];
    if (t >= t0 && t <= t1) {
      const f = (t - t0) / (t1 - t0);
      return Math.round(stops[i][1] + f * (stops[i + 1][1] - stops[i][1]));
    }
  }
  return stops[stops.length - 1][1];
}

