// not actually viridis, changed it to cividis like
function colorMapViridis(t) {
  t = Math.max(0, Math.min(1, t));

  const stops = [
    [0.0, 0, 32, 76],
    [0.25, 40, 80, 120],
    [0.5, 90, 130, 140],
    [0.75, 170, 180, 110],
    [1.0, 255, 233, 69]
  ];

  let i = 0;
  while (i < stops.length - 1 && t > stops[i + 1][0]) i++;

  const [t0, r0, g0, b0] = stops[i];
  const [t1, r1, g1, b1] = stops[i + 1];

  const u = (t - t0) / (t1 - t0);
  const r = Math.round(r0 + u * (r1 - r0));
  const g = Math.round(g0 + u * (g1 - g0));
  const b = Math.round(b0 + u * (b1 - b0));

  return `rgb(${r},${g},${b})`;
}

function rgbStringToObject(rgb) {
  const m = String(rgb).match(/rgb\(\s*([0-9.]+)\s*,\s*([0-9.]+)\s*,\s*([0-9.]+)\s*\)/i);
  if (!m) return { r: 0, g: 0, b: 0 };
  return { r: Number(m[1]), g: Number(m[2]), b: Number(m[3]) };
}

function textColorForFill(fill) {
  const { r, g, b } = rgbStringToObject(fill);
  const luminance = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  return luminance < 140 ? '#ffffff' : '#111111';
}

function makeMiniHexMap(nodes, selectedNodeId, opts = {}) {
  const width = opts.width || 210;
  const height = opts.height || 170;
  const r = opts.r || 10;
  const pad = opts.pad || 16;
  const stroke = opts.stroke || '#666';
  const bgFill = opts.bgFill || '#ffffff';
  const activeFill = opts.activeFill || '#111111';
  const activeStroke = opts.activeStroke || '#111111';

  const xs = nodes.map(n => n.x);
  const ys = nodes.map(n => n.y);
  const xmin = Math.min(...xs);
  const xmax = Math.max(...xs);
  const ymin = Math.min(...ys);
  const ymax = Math.max(...ys);

  const dx = Math.max(1, xmax - xmin);
  const dy = Math.max(1, ymax - ymin);

  const usableW = width - 2 * pad - 2 * r;
  const usableH = height - 2 * pad - 2 * r;
  const scaleX = usableW / dx;
  const scaleY = usableH / dy;
  const scale = Math.min(scaleX, scaleY);

  let svg = `<svg viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" class="mini-hex-svg">`;

  for (const n of nodes) {
    const cx = (n.x - xmin) * scale + pad + r;
    const cy = height - ((n.y - ymin) * scale + pad + r);
    const isActive = Number(n.node_id) === Number(selectedNodeId);
    const fill = isActive ? activeFill : bgFill;
    const thisStroke = isActive ? activeStroke : stroke;

    svg += `
      <a href="node.html?id=${n.node_id}">
        <path
          d="${hexPath(cx, cy, r)}"
          fill="${fill}"
          stroke="${thisStroke}"
          stroke-width="${isActive ? 1.5 : 1.0}"
        >
          <title>Node ${n.node_id}</title>
        </path>
      </a>
    `;
  }

  svg += `</svg>`;
  return svg;
}

function attachSearchEnterHandlers(searchBtn, ticInput, sectorInput) {
  const onEnter = e => {
    if (e.key === 'Enter') {
      e.preventDefault();
      searchBtn.click();
    }
  };
  ticInput.addEventListener('keydown', onEnter);
  sectorInput.addEventListener('keydown', onEnter);
}

function loadNodePrefs() {
  let viewMode = 'ranked';
  let rankedCount = '10';
  let pageSize = '50';
  try {
    viewMode = localStorage.getItem('nodeViewMode') || 'ranked';
    rankedCount = localStorage.getItem('nodeRankedCount') || '10';
    pageSize = localStorage.getItem('nodePageSize') || '50';
  } catch (err) {
  }
  return { viewMode, rankedCount, pageSize };
}

function saveNodePrefs(prefs) {
  try {
    localStorage.setItem('nodeViewMode', prefs.viewMode);
    localStorage.setItem('nodeRankedCount', prefs.rankedCount);
    localStorage.setItem('nodePageSize', prefs.pageSize);
  } catch (err) {
  }
}
